package com.tekwatt.payment.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="wallet_entries")public class WalletEntry{@Id private UUID id;@Column(nullable=false)private UUID walletId;@Column(nullable=false,precision=14,scale=2)private BigDecimal amount;@Column(nullable=false,precision=14,scale=2)private BigDecimal balanceAfter;@Column(nullable=false,length=50)private String reason;@Column(length=120)private String reference;@Column(nullable=false,updatable=false)private Instant createdAt;protected WalletEntry(){}public WalletEntry(UUID w,BigDecimal a,BigDecimal b,String r,String ref){id=UUID.randomUUID();walletId=w;amount=a;balanceAfter=b;reason=r;reference=ref;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getWalletId(){return walletId;}public BigDecimal getAmount(){return amount;}public BigDecimal getBalanceAfter(){return balanceAfter;}public String getReason(){return reason;}public String getReference(){return reference;}public Instant getCreatedAt(){return createdAt;}}
